from pathlib import Path

SCHED = Path("/sgl-workspace/sglang/python/sglang/srt/managers/scheduler_pp_mixin.py")
s = SCHED.read_text()

old = '''                if self.pp_group.is_first_rank:\n                    if cur_batch.forward_mode.is_extend() or cur_batch.is_extend_in_batch:\n                        _mtp_ids = getattr(cur_batch, "prefill_input_ids_cpu", None)\n                        if _mtp_ids is None:\n                            _mtp_ids = getattr(cur_batch, "input_ids", None)\n                        if _mtp_ids is None:\n                            raise RuntimeError(\n                                "[MTP-PP-SOURCE-MISSING] PP0 has neither "\n                                "prefill_input_ids_cpu nor input_ids"\n                            )\n                        cur_batch._mtp_pp_input_ids = _mtp_ids.to(\n                            self.device, non_blocking=True\n                        ).detach().clone()\n                        if cur_batch._mtp_pp_input_ids.numel() > 0:\n                            logger.info(\n                                "[MTP-PP-SOURCE-IDS] ids=[%d,%d] tokens=%d",\n                                int(cur_batch._mtp_pp_input_ids.min().item()),\n                                int(cur_batch._mtp_pp_input_ids.max().item()),\n                                int(cur_batch._mtp_pp_input_ids.numel()),\n                            )\n'''

new = '''                if self.pp_group.is_first_rank:\n                    if cur_batch.forward_mode.is_extend() or cur_batch.is_extend_in_batch:\n                        # prefill_input_ids_cpu is only an execution staging buffer and\n                        # can be rewritten with PP-local/proxy payloads while the same\n                        # ScheduleBatch is recycled. Reconstruct vocabulary ids from\n                        # Req fill state, but first expose the exact phase so a stale\n                        # is_extend_in_batch flag cannot masquerade as a real prefill.\n                        _mtp_ranges = []\n                        for _req in cur_batch.reqs:\n                            _range = getattr(_req, "extend_range", None)\n                            if _range is not None:\n                                _mtp_ranges.append((int(_range.start), int(_range.end)))\n                            else:\n                                _mtp_ranges.append(None)\n                        _mtp_spec = getattr(cur_batch, "spec_info", None)\n                        logger.info(\n                            "[MTP-PP-PHASE] mode=%s is_extend_in_batch=%s "\n                            "spec=%s extend_num=%s reqs=%d ranges=%s",\n                            cur_batch.forward_mode,\n                            bool(cur_batch.is_extend_in_batch),\n                            type(_mtp_spec).__name__ if _mtp_spec is not None else None,\n                            getattr(cur_batch, "extend_num_tokens", None),\n                            len(cur_batch.reqs),\n                            _mtp_ranges,\n                        )\n\n                        # A non-EXTEND phase entering only because the sticky\n                        # is_extend_in_batch bit is set is the suspected PP/spec-v2\n                        # misclassification. Fail synchronously before touching CUDA\n                        # or constructing bogus token ids so the next log proves it.\n                        if not cur_batch.forward_mode.is_extend():\n                            raise RuntimeError(\n                                "[MTP-PP-STALE-EXTEND-FLAG] "\n                                f"mode={cur_batch.forward_mode} "\n                                f"is_extend_in_batch={cur_batch.is_extend_in_batch} "\n                                f"spec={type(_mtp_spec).__name__ if _mtp_spec is not None else None} "\n                                f"extend_num={getattr(cur_batch, 'extend_num_tokens', None)} "\n                                f"ranges={_mtp_ranges}"\n                            )\n\n                        _mtp_values = []\n                        for _req in cur_batch.reqs:\n                            _fill = _req.get_fill_ids()\n                            _range = getattr(_req, "extend_range", None)\n                            if _range is not None:\n                                _start = int(_range.start)\n                                _end = int(_range.end)\n                            else:\n                                _start = len(_req.prefix_indices)\n                                _end = len(_fill)\n                            _part = _fill[_start:_end]\n                            _mtp_values.extend(int(_tok) for _tok in _part)\n\n                        _expected = int(getattr(cur_batch, "extend_num_tokens", len(_mtp_values)))\n                        if len(_mtp_values) != _expected:\n                            _staging = getattr(cur_batch, "prefill_input_ids_cpu", None)\n                            _staging_n = int(_staging.numel()) if _staging is not None else -1\n                            raise RuntimeError(\n                                "[MTP-PP-REQ-LEN] "\n                                f"reconstructed={len(_mtp_values)} expected={_expected} "\n                                f"staging={_staging_n} ranges={_mtp_ranges}"\n                            )\n\n                        cur_batch._mtp_pp_input_ids = torch.tensor(\n                            _mtp_values, dtype=torch.int64, device=self.device\n                        )\n                        if cur_batch._mtp_pp_input_ids.numel() > 0:\n                            _min_id = int(cur_batch._mtp_pp_input_ids.min().item())\n                            _max_id = int(cur_batch._mtp_pp_input_ids.max().item())\n                            _vocab = int(self.model_config.vocab_size)\n                            if _min_id < 0 or _max_id >= _vocab:\n                                raise RuntimeError(\n                                    "[MTP-PP-REQ-OOB] "\n                                    f"ids=[{_min_id},{_max_id}] vocab={_vocab} "\n                                    f"mode={cur_batch.forward_mode} "\n                                    f"is_extend_in_batch={cur_batch.is_extend_in_batch} "\n                                    f"spec={type(_mtp_spec).__name__ if _mtp_spec is not None else None} "\n                                    f"extend_num={getattr(cur_batch, 'extend_num_tokens', None)} "\n                                    f"ranges={_mtp_ranges}"\n                                )\n                            _staging = getattr(cur_batch, "prefill_input_ids_cpu", None)\n                            if _staging is not None and _staging.numel() > 0:\n                                _smin = int(_staging.min().item())\n                                _smax = int(_staging.max().item())\n                                _sn = int(_staging.numel())\n                            else:\n                                _smin, _smax, _sn = 0, -1, 0\n                            logger.info(\n                                "[MTP-PP-REQ-SOURCE] ids=[%d,%d] tokens=%d "\n                                "staging=[%d,%d]/%d ranges=%s",\n                                _min_id, _max_id,\n                                int(cur_batch._mtp_pp_input_ids.numel()),\n                                _smin, _smax, _sn, _mtp_ranges,\n                            )\n'''

if "[MTP-PP-PHASE]" in s:
    print("native MTP PP phase diagnostic patch already present")
elif "[MTP-PP-REQ-SOURCE]" in s:
    # The ownership patch has already replaced the base block. Insert the phase\n    # diagnostic and stale-flag guard immediately before Req reconstruction.\n    needle = '''                        _mtp_values = []\n                        _mtp_ranges = []\n'''
    replacement = '''                        _mtp_ranges = []\n                        for _req in cur_batch.reqs:\n                            _range = getattr(_req, "extend_range", None)\n                            if _range is not None:\n                                _mtp_ranges.append((int(_range.start), int(_range.end)))\n                            else:\n                                _mtp_ranges.append(None)\n                        _mtp_spec = getattr(cur_batch, "spec_info", None)\n                        logger.info(\n                            "[MTP-PP-PHASE] mode=%s is_extend_in_batch=%s "\n                            "spec=%s extend_num=%s reqs=%d ranges=%s",\n                            cur_batch.forward_mode,\n                            bool(cur_batch.is_extend_in_batch),\n                            type(_mtp_spec).__name__ if _mtp_spec is not None else None,\n                            getattr(cur_batch, "extend_num_tokens", None),\n                            len(cur_batch.reqs),\n                            _mtp_ranges,\n                        )\n                        if not cur_batch.forward_mode.is_extend():\n                            raise RuntimeError(\n                                "[MTP-PP-STALE-EXTEND-FLAG] "\n                                f"mode={cur_batch.forward_mode} "\n                                f"is_extend_in_batch={cur_batch.is_extend_in_batch} "\n                                f"spec={type(_mtp_spec).__name__ if _mtp_spec is not None else None} "\n                                f"extend_num={getattr(cur_batch, 'extend_num_tokens', None)} "\n                                f"ranges={_mtp_ranges}"\n                            )\n                        _mtp_values = []\n'''
    if needle not in s:
        raise RuntimeError("native MTP PP Req reconstruction insertion point not found")
    s = s.replace(needle, replacement, 1)
    # Avoid appending each range twice in the already-patched block.
    s = s.replace('''                            _mtp_ranges.append((_start, _end))\n\n                        _expected =''', '''\n                        _expected =''', 1)
    # Enrich the existing OOB error with phase details.
    s = s.replace(
        '''                                    f"ids=[{_min_id},{_max_id}] vocab={_vocab} "\n                                    f"ranges={_mtp_ranges}"\n''',
        '''                                    f"ids=[{_min_id},{_max_id}] vocab={_vocab} "\n                                    f"mode={cur_batch.forward_mode} "\n                                    f"is_extend_in_batch={cur_batch.is_extend_in_batch} "\n                                    f"spec={type(_mtp_spec).__name__ if _mtp_spec is not None else None} "\n                                    f"extend_num={getattr(cur_batch, 'extend_num_tokens', None)} "\n                                    f"ranges={_mtp_ranges}"\n''',
        1,
    )
    SCHED.write_text(s)
    print("PATCHED native MTP PP phase diagnostics")
    print(SCHED)
elif old not in s:
    raise RuntimeError("native MTP PP source block not found")
else:
    s = s.replace(old, new, 1)
    SCHED.write_text(s)
    print("PATCHED native MTP PP source reconstruction with phase diagnostics")
    print(SCHED)
